 records.append(dict(evidence_id=eid,source_id=sid,printed_page=printed,pdf_page_one_based=pdf,image_path=path,image_sha256=sha(path),inspection={'agent':'unit18_source','method':'personally viewed page image with view_image and read the relevant print','date':'2026-10-28','scope':scope},retrieval_url=url,warning='Hash and rendering establish file identity only; the recorded visual reading is a separate actual inspection.'))
